using System;using System.Collections.Generic;namespace EJLive.Core.Security{public enum CommandState{Draft,Approved,Sent,Ack,Completed,Failed,Expired,Rejected,Cancelled}public enum RbacRole{Viewer,Operator,Support,Admin,SecurityAdmin}public class RemoteCommandEnvelope{public string CommandId{get;set;}public string CorrelationId{get;set;}public string CommandType{get;set;}public string TargetATM{get;set;}public string OperatorId{get;set;}public RbacRole RequiredRole{get;set;}public DateTime TimestampUtc{get;set;}public DateTime ExpiryUtc{get;set;}public string Payload{get;set;}public string Signature{get;set;}public CommandState State{get;set;}}public class CommandQueue{private List<RemoteCommandEnvelope> _c=new List<RemoteCommandEnvelope>();public void Enqueue(RemoteCommandEnvelope c)=>_c.Add(c);public int Count=>_c.Count;}public class CommandAuditService{private List<string> _l=new List<string>();public void Log(string action)=>_l.Add(DateTime.UtcNow.ToString(""O"")+""|""+action);public IReadOnlyList<string> GetLog()=>_l.AsReadOnly();}public class UnifiedRemoteCommandPolicy{public bool IsAuthorized(RemoteCommandEnvelope cmd,RbacRole role)=>DateTime.UtcNow<cmd.ExpiryUtc&&role>=cmd.RequiredRole;}public static class SecretRedactor{public static string Redact(string s)=>string.IsNullOrEmpty(s)?s:s.Length>4?s.Substring(0,2)+""****""+s.Substring(s.Length-2):""****"";}public class SafeRemoteCommandExecutor{private UnifiedRemoteCommandPolicy _p=new UnifiedRemoteCommandPolicy();private CommandAuditService _a=new CommandAuditService();public bool Execute(RemoteCommandEnvelope cmd,RbacRole role){if(!_p.IsAuthorized(cmd,role)){cmd.State=CommandState.Rejected;return false;}_a.Log(""BEFORE|""+cmd.CommandType);cmd.State=CommandState.Completed;_a.Log(""AFTER|""+cmd.CommandType);return true;}}}